parameters.jsCode:
// Parse the stringified JSON inside the output key
const cleanOutput = JSON.parse($json.output);

// Check if threatSummary is missing, null, or an empty string
if (!cleanOutput || !cleanOutput.threatSummary) {
  return [{
    json: {
      status: "API FAILURE",
      message: "The required threatSummary field was not found in the output."
    }
  }];
}

// Return the parsed values so n8n recognizes them as separate fields
return [{
  json: {
    companyName: cleanOutput.companyName,
    threatSummary: cleanOutput.threatSummary,
    techStack: cleanOutput.techStack,
    affected_software: cleanOutput.affected_software,
    attack_type: cleanOutput.attack_type,
    severity: cleanOutput.severity,
    dateFound: cleanOutput.dateFound,

    // REMOVE FIXED DEFAULTS TO FORCE DYNAMIC VALUES:
    relevance_score: cleanOutput.relevance_score, 
    remediation_action: cleanOutput.remediation_action
  }
}];

// --- CONFIGURATION POOLS FOR MAXIMUM VARIETY ---
const cybersecurityPrefixes = ['NetSec', 'Aegis', 'CoreShield', 'Sentinel', 'Nexus', 'Vertex', 'Horizon', 'Synapse', 'Citadel', 'Bastion', 'Fortress', 'Apex', 'Vanguard', 'Vector', 'Matrix', 'Pinnacle', 'Catalyst', 'OmniSec'];
const technicalSuffixes = ['Systems', 'Labs', 'Networks', 'Tech', 'Solutions', 'Dynamics', 'Cyber', 'Intelligence', 'Security', 'Global', 'Platforms', 'Engineering'];

// Targeted corporate infrastructure tech stacks
const techStacks = [
  'JavaScript, Node.js, Electron',
  'PostgreSQL, Redis, Docker containers',
  'Apache HTTP Server, Ubuntu Linux, OpenSSL',
  'Kubernetes clusters, Terraform infrastructure, AWS IAM',
  'Nginx web servers, Python applications, GitHub Actions CI/CD',
  'Active Directory, Windows Server 2022, IIS',
  'MongoDB databases, Express.js apps, React frameworks',
  'Cisco IOS XE routers, BGP routing infrastructure, Fortinet firewalls'
];

// ====================================================================
// PART 1 & 3: CRITICAL CONCEPTS (Triggers High & Medium Severities)
// ====================================================================
const criticalConcepts = [
  // --- HIGH SEVERITY LOGIC (Zero-Days, RCEs, Critical Infra Breaches) ---
  'Remote Code Execution CVE patch advisory',
  'Zero-day local privilege escalation exploit',
  'Supply chain backdoor dependency vulnerability',
  'Unauthenticated authentication bypass vulnerability',
  'Critical Remote Command Injection disclosure',
  'Ransomware threat actor initial access vector',
  'Active directory domain escalation exploit',
  'Desynchronization HTTP request smuggling CVE',

  // --- MEDIUM SEVERITY LOGIC (Requires Auth, Local Access, or User Interaction) ---
  'Stored Cross-Site Scripting XSS proof of concept',
  'SQL Injection vulnerability authenticated bypass',
  'Insecure Direct Object Reference IDOR data leak',
  'Server-Side Request Forgery SSRF internal pivot',
  'Privileged Path Traversal arbitrary file read',
  'Broken Object Level Authorization BOLA exposure',
  'Cross-Site Request Forgery CSRF token bypass',
  'Information disclosure sensitive metadata leakage'
];

// ====================================================================
// PART 2: INFORMATIONAL CONCEPTS (Triggers Low/None Severities)
// ====================================================================
const informationalConcepts = [
  'Minor patch update release notes engineering',
  'Security advisory hardening guidance checklist',
  'Stable version changelog software optimization',
  'Non-critical regulatory compliance policy update',
  'Deprecation notice legacy module migration guide',
  'Routine maintenance window infrastructure stability',
  'Performance benchmarking telemetry adjustment log',
  'Vendor software package structural refactoring note',
  'TLS cipher suite configuration hardening best practice',
  'Open-source package minor bugfix release'
];
// --- SELECTION ENGINE ---
function getRandomItem(array) {
  return array[Math.floor(Math.random() * array.length)];
}

// Generate an authentic corporate tech identity
const generatedCompany = `${getRandomItem(cybersecurityPrefixes)} ${getRandomItem(technicalSuffixes)}`;
const assignedStack = getRandomItem(techStacks);

// Pre-compile advanced search strings to maximize SerpAPI search efficiency
const targetCriticalConcept = getRandomItem(criticalConcepts);
const targetInformationalConcept = getRandomItem(informationalConcepts);

// Output matching property values cleanly down the canvas stream
return [{
  json: {
    companyName: generatedCompany,
    techStack: assignedStack,
    criticalSearchQuery: `critical vulnerability "${targetCriticalConcept}" ${assignedStack.split(',')[0]}`,
    informationalSearchQuery: `software update "${targetInformationalConcept}" ${assignedStack.split(',')[0]}`
  }
}];

